package com.kgps.result.ai.offline

import java.io.ByteArrayInputStream
import java.io.InputStream
import java.util.zip.GZIPInputStream

/**
 * Compiled-in gzip+base64 copy of the trained KGDC digit CNN weights
 * so offline scanning always works even if APK assets/raw resources are stripped or stale.
 */
internal object EmbeddedDigitModels {

    fun openEnglishStream(): InputStream = GZIPInputStream(ByteArrayInputStream(decodeBase64(enB64())))

    fun openBengaliStream(): InputStream = GZIPInputStream(ByteArrayInputStream(decodeBase64(bnB64())))

    private fun enB64(): String = buildString(162192) {
        append("")
        append("")
        append("")
        append("")
        append("")
    }

    private fun bnB64(): String = buildString(155480) {
        append("")
        append("")
        append("")
        append("")
    }

    private val B64_INV = IntArray(256) { -1 }.apply {
        val alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        for (i in alpha.indices) this[alpha[i].code] = i
    }

    private fun decodeBase64(s: String): ByteArray {
        val len = s.length
        var pad = 0
        if (len > 0 && s[len - 1] == '=') pad++
        if (len > 1 && s[len - 2] == '=') pad++
        val out = ByteArray((len * 3) / 4 - pad)
        var outIdx = 0
        var i = 0
        while (i < len) {
            val c0 = B64_INV[s[i].code and 0xFF]
            val c1 = B64_INV[s[i + 1].code and 0xFF]
            val c2 = if (s[i + 2] == '=') 0 else B64_INV[s[i + 2].code and 0xFF]
            val c3 = if (s[i + 3] == '=') 0 else B64_INV[s[i + 3].code and 0xFF]
            val v = (c0 shl 18) or (c1 shl 12) or (c2 shl 6) or c3
            out[outIdx++] = ((v ushr 16) and 0xFF).toByte()
            if (outIdx < out.size) out[outIdx++] = ((v ushr 8) and 0xFF).toByte()
            if (outIdx < out.size) out[outIdx++] = (v and 0xFF).toByte()
            i += 4
        }
        return out
    }
}
